		snap := c.Snapshot(&ai)
		ai.FlatDmg = snap.Stats.TotalDEF()
		ai.FlatDmg *= thrustDefScaling[c.TalentLvlSkill()]
		c.Core.QueueAttackWithSnap(ai, snap, combat.NewCircleHitOnTarget(t, nil, 2.5), 1)

