			return
		}

		if atk.Info.ActorIndex != c.Core.Player.Active() {
			return
		}

		if !c.StatusIsActive(c6Key) {
			return
		}

		switch atk.Info.AttackTag {
		case attacks.AttackTagDirectStellarConduct:
		case attacks.AttackTagDirectStellarSwirl:
		default:
			return
		}

		c.c6Stacks -= 1
		amt := 6 * c.TotalAtk()
		if c.Core.Flags.LogDebug {
			c.Core.Log.NewEvent("Qiqi C6 proc dmg add", glog.LogPreDamageMod, atk.Info.ActorIndex).
				Write("before", atk.Info.FlatDmg).
				Write("addition", amt).
				Write("c6 stacks left", c.c6Stacks)
		}
		atk.Info.FlatDmg += amt
	}

func(args ...any) {
		atk := args[1].(*info.AttackEvent)
		consumeStack := true
		if atk.Info.Element != attributes.Cryo {
			return
		}

		switch atk.Info.AttackTag {
		case attacks.AttackTagElementalBurst:
		case attacks.AttackTagElementalArt:
		case attacks.AttackTagElementalArtHold:
		case attacks.AttackTagNormal:
			consumeStack = c.Base.Cons < 6
		case attacks.AttackTagExtra:
			consumeStack = c.Base.Cons < 6
		case attacks.AttackTagPlunge:
		default:
			return
		}

		char := c.Core.Player.ByIndex(atk.Info.ActorIndex)

		if !char.StatusIsActive(quillKey) {
			return
		}

		if char.Tags[quillKey] > 0 {
			amt := skillpp[c.TalentLvlSkill()] * c.TotalAtk()
			if consumeStack { // c6
				char.Tags[quillKey]--
			}

			if c.Core.Flags.LogDebug {
				c.Core.Log.NewEvent("Shenhe Quill proc dmg add", glog.LogPreDamageMod, atk.Info.ActorIndex).
					Write("before", atk.Info.FlatDmg).
					Write("addition", amt).
					Write("effect_ends_at", char.StatusExpiry(quillKey)).
					Write("quill_left", char.Tags[quillKey])
			}

			atk.Info.FlatDmg += amt
			if c.Base.Cons >= 4 {
				atk.Callbacks = append(atk.Callbacks, c.c4CB)
			}
		}
	}

func(args ...any) {
		atk := args[1].(*info.AttackEvent)
		switch atk.Info.AttackTag {
		case attacks.AttackTagElementalArt:
		case attacks.AttackTagElementalArtHold:
		default:
			return
		}

		if atk.Info.ActorIndex == c.Index() {
			return
		}

		active := c.Core.Player.ActiveChar()
		if active.Index() == atk.Info.ActorIndex {
			return
		}

		if !c.StatusIsActive(convalescenceKey) || c.Tag(convalescenceKey) == 0 {
			return
		}
		c.SetTag(convalescenceKey, c.Tag(convalescenceKey)-1)

		hp := max(c.MaxHP()-baseConvalescenceHP, 0)
		var amt float64
		if c.Base.Cons >= 1 {
			amt = min(c1FlatConvalescenceCap, hp*c1FlatConvalescenceIncrease)
		} else {
			amt = min(flatConvalescenceCap, hp*flatConvalescenceIncrease)
		}

		if c.Core.Flags.LogDebug {
			c.Core.Log.NewEvent("Sigewinne A1 proc dmg add", glog.LogPreDamageMod, atk.Info.ActorIndex).
				Write("before", atk.Info.FlatDmg).
				Write("addition", amt).
				Write("effect_ends_at", c.StatusExpiry(convalescenceKey)).
				Write("quill_left", c.Tag(convalescenceKey))
		}

		atk.Info.FlatDmg += amt
	}

func(args ...any) {
		ae := args[1].(*info.AttackEvent)
		if ae.Info.AttackTag != attacks.AttackTagPlunge {
			return
		}

		// Collision has 0 durability. Don't buff collision damage
		if ae.Info.Durability == 0 {
			return
		}

		if !c.StatusIsActive(a4WindowKey) {
			return
		}

		if c.StatusIsActive(a4ICDKey) {
			return
		}

		// A4 cap
		amt := min(c.a4Max, c.a4Ratio*c.a4Atk)

		c.Core.Log.NewEvent("Xianyun A4 proc dmg add", glog.LogPreDamageMod, ae.Info.ActorIndex).
			Write("atk", c.a4Atk).
			Write("ratio", c.a4Ratio).
			Write("addition", amt)

		ae.Info.FlatDmg += amt
		c.AddStatus(a4ICDKey, 0.4*60, true)
	}

func(args ...any) {
		ae := args[1].(*info.AttackEvent)

		if ae.Info.AttackTag != attacks.AttackTagNormal {
			return
		}
		char := c.Core.Player.ByIndex(ae.Info.ActorIndex)
		// do nothing if buff gone or burst count gone
		if char.Tags[burstBuffKey] == 0 {
			return
		}
		if !char.StatusIsActive(burstBuffKey) {
			return
		}

		finalBurstBuff := burstBuff[c.TalentLvlBurst()] + c.a4()
		dmgAdded := c.TotalDef(false) * finalBurstBuff
		ae.Info.FlatDmg += dmgAdded

		char.Tags[burstBuffKey] -= 1

		c.Core.Log.NewEvent("yunjin burst adding damage", glog.LogPreDamageMod, ae.Info.ActorIndex).
			Write("damage_added", dmgAdded).
			Write("stacks_remaining_for_char", char.Tags[burstBuffKey]).
			Write("burst_def_pct", finalBurstBuff)
	}
